actions.script:
const scriptPages = allowScriptPages != null && allowScriptPages !== '' ? allowScriptPages : originalValue?.allowScriptPages
const root = String((rootPageLocation != null && rootPageLocation !== '' ? rootPageLocation : originalValue?.rootPageLocation) || '')
const ownDb = `dbresource://WikiSpace/${wikiSpaceId}.`
if (scriptPages == 'Y' && !(root.startsWith(ownDb) && !root.slice(ownDb.length).includes('/') && !root.includes('..')))
    throw new Error(ec.l10n.localize("A space whose script pages run keeps its pages in its own place in the database, not in a repository or another place"))
if (!ec.artifactExecution.authzDisabled()) {
    const updating = eecaOperation == 'update' && originalValue != null
    const changed = (value, original) => value != null && value !== '' && (!updating || value != original)
    const refuse = (text) => { throw new Error(ec.l10n.localize(text)) }
    if (changed(allowScriptPages, originalValue?.allowScriptPages) && allowScriptPages == 'Y' && !ec.user.hasPermission('DATABASE_ADMIN'))
        refuse('A space whose script pages run needs the DATABASE_ADMIN permission')
    if (changed(decoratorScreenLocation, originalValue?.decoratorScreenLocation) && !ec.user.hasPermission('DATABASE_ADMIN'))
        refuse('A screen around the pages of a space needs the DATABASE_ADMIN permission')
    const admin = ec.user.isInGroup('ADMIN')
    if (changed(allowAnyHtml, originalValue?.allowAnyHtml) && allowAnyHtml == 'Y' && !admin)
        refuse('Only a system administrator allows any HTML in a space')
    if (changed(rootPageLocation, originalValue?.rootPageLocation)) {
        const location = String(rootPageLocation)
        const id = String(wikiSpaceId)
        const own = (prefix) => location.startsWith(prefix) && !location.slice(prefix.length).includes('/')
        // another place: a component's for a system administrator, any other (another record's
        // dbresource text, a remote location) only with DATABASE_ADMIN, as Security.eecas.xml holds the
        // other location fields (plans/archive/Security-Review-Low.md SEC-SCR-92)
        let allowed = !location.includes('..') &&
                (own(`dbresource://WikiSpace/${id}.`) || own(`git://WIKI_${id}/${id}.`)
                    || (admin && location.startsWith('component://')) || ec.user.hasPermission('DATABASE_ADMIN'))
        const git = /^git:\/\/([^\/]+)\//.exec(location)
        if (!allowed && git && !location.includes('..')) {
            ec.message.pushErrors()
            try {
                allowed = !!ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess')
                        .parameter('repositoryId', git[1]).disableAuthz().call()?.canUpdate && !ec.message.hasError()
            } catch (e) {
                allowed = false
            } finally {
                ec.message.clearErrors()
                ec.message.popErrors()
            }
        }
        if (!allowed) refuse("A space's pages go under its own place, a repository the user may change, or a component's place for a system administrator: another needs the DATABASE_ADMIN permission")
    }
}
